import sys
import math

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

def max_matching(graph):
    n1 = len(graph)
    n2 = len(graph[0]) if n1 > 0 else 0
    match = [-1] * n2
    match_count = 0

    def dfs_match(u, visited):
        for v in range(n2):
            if graph[u][v] and not visited[v]:
                visited[v] = True
                if match[v] == -1 or dfs_match(match[v], visited):
                    match[v] = u
                    return True
        return False

    for u in range(n1):
        visited = [False] * n2
        if dfs_match(u, visited):
            match_count += 1
    return match_count

def bruteforce(n, m):
    even_points = []
    odd_points = []
    for i in range(n):
        for j in range(m):
            if (i + j) % 2 == 0:
                even_points.append(Point(i, j))
            else:
                odd_points.append(Point(i, j))
    adjacency = [[False] * len(odd_points) for _ in range(len(even_points))]
    for i, ep in enumerate(even_points):
        for j, op in enumerate(odd_points):
            dist = abs(ep.x - op.x) + abs(ep.y - op.y)
            if dist == 3:
                adjacency[i][j] = True
    return 2 * max_matching(adjacency)

def main():
    input_lines = sys.stdin.read().splitlines()
    tokens = []
    for line in input_lines:
        tokens.extend(line.strip().split())
    index = 0

    def get_next_int():
        nonlocal index
        val = int(tokens[index])
        index += 1
        return val

    n = get_next_int()
    m = get_next_int()
    if n > m:
        n, m = m, n

    if n == 1:
        m -= 1
        pattern = [0, 0, 0, 2, 4, 6]
        result = (m // 6) * 6 + pattern[m % 6]
        print(result)
        return
    elif n == 2:
        if m < 20:
            print(bruteforce(n, m))
        else:
            print(n * m)
        return
    elif n == 3:
        if m < 20:
            print(bruteforce(n, m))
        else:
            res = n * m
            if res % 2 != 0:
                res -= 1
            print(res)
        return
    total_cells = n * m
    if total_cells % 2 != 0:
        total_cells -= 1
    print(total_cells)

if __name__ == "__main__":
    main()

